import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { it, expect, vi } from "vitest";
import { LessonEditor } from "./LessonEditor.jsx";

it("saves the typed title", async () => {
  const onSave = vi.fn();
  const user = userEvent.setup();
  render(<LessonEditor onSave={onSave} />);

  await user.type(screen.getByLabelText("Lesson title"), "Loops");
  await user.click(screen.getByRole("button", { name: "Save lesson" }));

  expect(onSave).toHaveBeenCalledWith({ title: "Loops" });
  expect(screen.getByRole("status")).toHaveTextContent("Saved");
});
```

| Priority | Query | Use for |
|---|---|---|
| 1. | getByRole + name. | buttons, links, headings, dialogs. |
| 2. | getByLabelText. | form fields. |
| 3. | getByText. | plain text content. |
| last. | getByTestId. | no role, label or text available. |

| Prefix | Behaviour |
|---|---|
| getBy. | exactly one, or throws. |
| queryBy. | returns null if missing (for "not there" checks). |
| findBy. | waits for it to appear (async). |

